using UnityEngine;

namespace TruckSim.Audio
{
    /// <summary>
    /// Everything the player truck plays, as one asset. Generated by the editor importer
    /// (Game.Editor.Audio.VehicleAudioImporter) from tools/audio's manifest.json into
    /// Assets/_Project/Audio/Generated/Resources/VehicleAudio/ (gitignored, regenerated from the WAVs), and loaded at
    /// runtime with <see cref="LoadDefault"/>. Missing library = silent game with a warning, never an error.
    /// </summary>
    public sealed class VehicleAudioLibrary : ScriptableObject
    {
        public const string ResourcePath = "VehicleAudio/VehicleAudioLibrary";

        public EngineSoundBank exteriorEngine, cabEngine, exteriorEngineBrake, cabEngineBrake;
        public AudioClip turboWhistleLoop, turboLiftoff;
        public AudioClip airBrakeRelease, parkingBrakeSet, airDryerPurge, gearshiftAir;
        public AudioClip roadRollLoop, windLoop, gearWhineLoop;
        [Tooltip("manifest.json generator line and clip count, for the log.")]
        public string sourceInfo;

        public static VehicleAudioLibrary LoadDefault() => Resources.Load<VehicleAudioLibrary>(ResourcePath);
    }
}
